import { getWalletErrorMessage } from "./walletErrors";

export function getAnswerSubmissionErrorMessage(error) {
    const message = String(error?.message || "").toLowerCase();
    if (message.includes("answer_confirmation_pending")) return "回答の取引は送信済みですが、結果をまだ確認できません。自動再送はしていません。MetaMask の取引履歴を確認してください。再度送信ボタンを押した場合も、まず送信済み取引の結果を確認します。";
    if (message.includes("answer_submission_in_progress")) return "ほかの回答の送信・結果確認が進行中です。MetaMask の保留中の確認画面と取引履歴を確認し、結果を待ってください。";
    if (message.includes("answer_previous_transaction_confirmed")) return "前回の取引の完了を確認しました。今回入力した回答は送信していません。問題を再読み込みし、提出済みの回答を確認してください。";
    const walletMessage = getWalletErrorMessage(error);
    if (walletMessage) return walletMessage;
    if (message.includes("answer_gas_estimation_failed")) return "回答の取引を事前確認できなかったため、MetaMask への送信を停止しました。締め切り・回答済み状態・手数料用 POL・通信状態を確認してください。入力内容は残しています。";
    if (message.includes("answer_transaction_not_sent")) return "回答の取引は送信されていません。MetaMask の確認画面を確認してください。入力内容は残しています。";
    return "";
}
